        "Configure reusable inspection checklists per case type. Checklists are versioned. Active inspections always use the version they started with.": "Configure reusable inspection checklists per case type. Checklists are versioned. Active inspections always use the version they started with.",
        "Configure statutory term definitions per zaaktype (legal basis, duration, validity). Saving a new version automatically sets validFrom=tomorrow on the new version and validUntil=today on the prior version. New cases use the latest version; running cases keep the version they were bound to.": "Configure statutory term definitions per zaaktype (legal basis, duration, validity). Saving a new version automatically sets validFrom=tomorrow on the new version and validUntil=today on the prior version. New cases use the latest version; running cases keep the version they were bound to.",
