        "What this status MEANS in a process, independent of what it is called. A shipped flow moves a case by role, so it works on a case type that calls its working phase Beoordeling or Onderzoek rather than In behandeling. Leave it empty for a status no flow needs to address.": "What this status MEANS in a process, independent of what it is called. A shipped flow moves a case by role, so it works on a case type that calls its working phase Beoordeling or Onderzoek rather than In behandeling. Leave it empty for a status no flow needs to address.",
        "Verplicht value-type embedded in elke sociaal-domein zaak. Legt categorieën bijzondere persoonsgegevens (AVG art. 9), rechtvaardiging, bewaartermijn en toegangsbeperking vast. Zaak kan niet worden opgeslagen zonder dit blok.": "Verplicht value-type embedded in elke sociaal-domein zaak. Legt categorieën bijzondere persoonsgegevens (AVG art. 9), rechtvaardiging, bewaartermijn en toegangsbeperking vast. Zaak kan niet worden opgeslagen zonder dit blok.",
        "Variant": "Variant",
        "Which route through the case type this workflow describes. A case type may carry several routes, and one workflow per route can be active at a time. Leave this alone when the case type has one route. Example: a handhavingszaak runs the ordinary route under Awb 5:24 and the spoedeisende route under Awb 5:31.": "Which route through the case type this workflow describes. A case type may carry several routes, and one workflow per route can be active at a time. Leave this alone when the case type has one route. Example: a handhavingszaak runs the ordinary route under Awb 5:24 and the spoedeisende route under Awb 5:31.",
        "The default route through this case type: the workflow a case follows when it is not given one of its own. A case type may carry several routes, and this names the one new cases take. When unset, a case falls through to the case type's only active workflow. A case keeps the workflow it was bound to, even after a newer version is published (see case.workflowTemplate and case.workflowVersion).": "The default route through this case type: the workflow a case follows when it is not given one of its own. A case type may carry several routes, and this names the one new cases take. When unset, a case falls through to the case type's only active workflow. A case keeps the workflow it was bound to, even after a newer version is published (see case.workflowTemplate and case.workflowVersion).",
        "The decidiq app provides decision-making for this case. Install or enable decidiq to manage proposals, advice and decisions here.": "The decidiq app provides decision-making for this case. Install or enable decidiq to manage proposals, advice and decisions here.",
