        "The processing deadline of this case's type, as an ISO 8601 duration. Copied from caseType.processingDeadline by x-openregister-calculations.statutoryTerm.": "The processing deadline of this case's type, as an ISO 8601 duration. Copied from caseType.processingDeadline by x-openregister-calculations.statutoryTerm.",
        "Colour": "Colour",
        "The hue this status is drawn in, on the status badge and as the Workflow board column header. A name from the NL Design System palette rather than a hex value, so a themed install repoints the token and every badge follows. Leave it empty and the status renders grey.": "The hue this status is drawn in, on the status badge and as the Workflow board column header. A name from the NL Design System palette rather than a hex value, so a themed install repoints the token and every badge follows. Leave it empty and the status renders grey.",
        "Hidden in lists": "Hidden in lists",
        "Whether cases in this status stay out of the Cases index. A closed status fills the list with work nobody is doing; marking it hidden keeps it off every lens except Closed. The case carries the flag as the calculated statusHiddenInLists so the list filters it server-side.": "Whether cases in this status stay out of the Cases index. A closed status fills the list with work nobody is doing; marking it hidden keeps it off every lens except Closed. The case carries the flag as the calculated statusHiddenInLists so the list filters it server-side.",
        "Status hidden in lists": "Status hidden in lists",
        "Whether the case sits at a status marked hidden in lists. Computed declaratively by OpenRegister from the linked statusType's hiddenInLists flag (x-openregister-calculations.statusHiddenInLists); the Cases index filters statusHiddenInLists=false on every lens but Closed.": "Whether the case sits at a status marked hidden in lists. Computed declaratively by OpenRegister from the linked statusType's hiddenInLists flag (x-openregister-calculations.statusHiddenInLists); the Cases index filters statusHiddenInLists=false on every lens but Closed.",
        "The case type this one derives from. A child inherits the parent's statuses, results, properties and deadlines, and declares only what differs: a row the child gives the same name replaces the parent's. Leave it empty for a type that stands on its own. A chain that returns to itself is refused on save, and the chain is at most three deep.": "The case type this one derives from. A child inherits the parent's statuses, results, properties and deadlines, and declares only what differs: a row the child gives the same name replaces the parent's. Leave it empty for a type that stands on its own. A chain that returns to itself is refused on save, and the chain is at most three deep.",
        "The folder this case type sits in on the Case types index, a free word rather than a fixed list: an organisation's own grouping (Vergunningen, Sociaal domein, Handhaving) is the one it recognises. Types with no category are listed under All case types with everything else.": "The folder this case type sits in on the Case types index, a free word rather than a fixed list: an organisation's own grouping (Vergunningen, Sociaal domein, Handhaving) is the one it recognises. Types with no category are listed under All case types with everything else.",
        "The case type this attribute belongs to. Leave it empty and the attribute is SHARED: it is listed on every case type's Properties tab under Shared attributes, so one Kenteken is authored once rather than copied per type.": "The case type this attribute belongs to. Leave it empty and the attribute is SHARED: it is listed on every case type's Properties tab under Shared attributes, so one Kenteken is authored once rather than copied per type.",
        "Processes personal data": "Processes personal data",
        "Personal data categories": "Personal data categories",
        "Processing activity": "Processing activity",
        "Whether cases of this type process personal data. Answer it on the type rather than per case: it is a property of the process, and a case handler is not the person who decides it.": "Whether cases of this type process personal data. Answer it on the type rather than per case: it is a property of the process, and a case handler is not the person who decides it.",
        "Which categories of personal data cases of this type process. The last seven are AVG article 9 special categories: naming one here is the record that says the extra safeguards apply.": "Which categories of personal data cases of this type process. The last seven are AVG article 9 special categories: naming one here is the record that says the extra safeguards apply.",
        "The AVG article 6 basis on which cases of this type process personal data. OpenRegister's own vocabulary verbatim, in English: its Verwerkingsactiviteit mapper refuses anything else, and this value is what pairs a case type with the activity in the verwerkingsregister.": "The AVG article 6 basis on which cases of this type process personal data. OpenRegister's own vocabulary verbatim, in English: its Verwerkingsactiviteit mapper refuses anything else, and this value is what pairs a case type with the activity in the verwerkingsregister.",
        "The code of the activity in OpenRegister's verwerkingsregister that cases of this type are logged under, as SeedVerwerkingsactiviteiten upserts them (zaakafhandeling, behandelen-omgevingsvergunning, behandelen-bezwaarschrift, behandelen-woo-verzoek, behandelen-klacht, klantcontact-registratie, zaak-archivering). A string rather than a $ref until OpenRegister exposes the verwerkingsregister as a referenceable schema.": "The code of the activity in OpenRegister's verwerkingsregister that cases of this type are logged under, as SeedVerwerkingsactiviteiten upserts them (zaakafhandeling, behandelen-omgevingsvergunning, behandelen-bezwaarschrift, behandelen-woo-verzoek, behandelen-klacht, klantcontact-registratie, zaak-archivering). A string rather than a $ref until OpenRegister exposes the verwerkingsregister as a referenceable schema.",
