        "We read all {count} systems on {date}. Open source moves fast, so some of these ratings are already out of date. Check that date before you rely on them.": "We read all {count} systems on {date}. Open source moves fast, so some of these ratings are already out of date. Check that date before you rely on them.",
        "We read {count} of the {total} systems on {date}. Open source moves fast, so some of these ratings are already out of date. Check that date before you rely on them.": "We read {count} of the {total} systems on {date}. Open source moves fast, so some of these ratings are already out of date. Check that date before you rely on them.",
        "About the {system} column": "About the {system} column",
        "We read {system} on {date}, not on the date above. Its column joined this table on {added}.": "We read {system} on {date}, not on the date above. Its column joined this table on {added}.",
        "{system} owns no data. The case, its documents and its retention live in {register}. A row we score in our own shape often falls outside {system} by design. Its column reads low for that reason, which flatters us. Read the gap as a difference in architecture, not as a weaker product.": "{system} owns no data. The case, its documents and its retention live in {register}. A row we score in our own shape often falls outside {system} by design. Its column reads low for that reason, which flatters us. Read the gap as a difference in architecture, not as a weaker product.",
