        "Before you use this table": "Before you use this table",
        "We strongly advise you to run your own evaluation. This table does not replace testing against your own requirements.": "We strongly advise you to run your own evaluation. This table does not replace testing against your own requirements.",
        "The case number. Filled declaratively by OpenRegister (x-openregister-calculations.identifier) as YEAR-NNNN, e.g. 2026-0042, where the year comes from startDate and NNNN from a yearly sequence. A number supplied on create is KEPT: the expression coalesces the given value ahead of the sequence, so an imported or migrated case keeps the number it already had. The sequence is not consumed in that case, because coalesce stops at the first non-null operand.": "The case number. Filled declaratively by OpenRegister (x-openregister-calculations.identifier) as YEAR-NNNN, e.g. 2026-0042, where the year comes from startDate and NNNN from a yearly sequence. A number supplied on create is KEPT: the expression coalesces the given value ahead of the sequence, so an imported or migrated case keeps the number it already had. The sequence is not consumed in that case, because coalesce stops at the first non-null operand.",
        "Simulated": "Simulated",
        "Limited": "Limited",
        "Berichtenbox": "Berichtenbox",
        "Document templates": "Document templates",
        "Messages to a citizen's Mijn Overheid Berichtenbox.": "Messages to a citizen's Mijn Overheid Berichtenbox.",
        "Rendering a besluit or a letter from a template, which Filinq does.": "Rendering a besluit or a letter from a template, which Filinq does.",
        "No Berichtenbox adapter is configured, so messages are simulated. Nothing reaches Mijn Overheid. Name a real adapter class in the berichtenbox_adapter setting to send for real.": "No Berichtenbox adapter is configured, so messages are simulated. Nothing reaches Mijn Overheid. Name a real adapter class in the berichtenbox_adapter setting to send for real.",
        "Filinq is not installed, so every beschikking is rendered by a mock. Install filinq, then name its adapter class in the beschikking_template_adapter setting.": "Filinq is not installed, so every beschikking is rendered by a mock. Install filinq, then name its adapter class in the beschikking_template_adapter setting.",
        "Filinq is installed but no template adapter is configured, so every beschikking is rendered by a mock. Name filinq's adapter class in the beschikking_template_adapter setting.": "Filinq is installed but no template adapter is configured, so every beschikking is rendered by a mock. Name filinq's adapter class in the beschikking_template_adapter setting.",
        "The adapter class named in %1$s cannot be used: %2$s is missing or does not implement the seam. A mock adapter is running in its place.": "The adapter class named in %1$s cannot be used: %2$s is missing or does not implement the seam. A mock adapter is running in its place.",
        "The adapter class named in %1$s could not be built. A mock adapter is running in its place.": "The adapter class named in %1$s could not be built. A mock adapter is running in its place.",
        "A mock adapter answers here. No message reaches Mijn Overheid. Set berichtenbox_adapter to a real adapter class.": "A mock adapter answers here. No message reaches Mijn Overheid. Set berichtenbox_adapter to a real adapter class.",
        "A mock adapter answers here. No template reaches Filinq. Set beschikking_template_adapter to a real adapter class.": "A mock adapter answers here. No template reaches Filinq. Set beschikking_template_adapter to a real adapter class.",
        "We corrected {count} of our own ratings on {date}, because we had shipped the capability since the reading. We do not correct the other {others} columns that way. Those ratings are as we read them, on the dates given here.": "We corrected {count} of our own ratings on {date}, because we had shipped the capability since the reading. We do not correct the other {others} columns that way. Those ratings are as we read them, on the dates given here.",
        "Every system here is a municipal case system or a workflow engine, and the list is drawn from what they do, in the shape we do it. A capability none of them has is missing from the list, not from the market. A product that splits the work differently scores low without being worse, and that bias runs in our favour. We add rows as we read more systems, so a lower score in a later release can mean the list grew rather than the product shrank.": "Every system here is a municipal case system or a workflow engine, and the list is drawn from what they do, in the shape we do it. A capability none of them has is missing from the list, not from the market. A product that splits the work differently scores low without being worse, and that bias runs in our favour. We add rows as we read more systems, so a lower score in a later release can mean the list grew rather than the product shrank.",
