        "The version that replaced this one, written the moment that version is published. A version with this filled in keeps running its own cases and is no longer offered for new ones. Empty means this is the version in use.": "The version that replaced this one, written the moment that version is published. A version with this filled in keeps running its own cases and is no longer offered for new ones. Empty means this is the version in use.",
        "The version this one was made from. Follow it back and you get the whole history of the case type, including the version any long-running case is still on.": "The version this one was made from. Follow it back and you get the whole history of the case type, including the version any long-running case is still on.",
        "Which version of this case type you are looking at. A case type is never edited once cases run on it: you make a new version, and the new version is a new object carrying its own statuses, results and properties. Version 1 is a case type nobody has versioned yet.": "Which version of this case type you are looking at. A case type is never edited once cases run on it: you make a new version, and the new version is a new object carrying its own statuses, results and properties. Version 1 is a case type nobody has versioned yet.",
        "A mail whose subject carries no case number, or one that no longer exists, becomes a case of this type. Leave it empty and the mail stays unread in the mailbox, which is what happens today.": "A mail whose subject carries no case number, or one that no longer exists, becomes a case of this type. Leave it empty and the mail stays unread in the mailbox, which is what happens today.",
