        "{total} capabilities. Dossiq has {yes}, partly has {partial}, is missing {no}. {pending} more proposed.": "{total} capabilities. Dossiq has {yes}, partly has {partial}, is missing {no}. {pending} more proposed.",
        "Another {count} capabilities are proposed and not yet rated. We read our own code for each of them. We have not read the other {others} systems against them, so they are in no total on this page. A proposal becomes a row when every system has been read against it.": "Another {count} capabilities are proposed and not yet rated. We read our own code for each of them. We have not read the other {others} systems against them, so they are in no total on this page. A proposal becomes a row when every system has been read against it.",
