        "What makes a case unread": "What makes a case unread",
        "The changes that make a case of this type unread again for the people who have already seen it. Leave it empty for the default: the status moved, a document arrived, somebody wrote. A change that is not named here is a technical touch and lights up nothing, which is what keeps a bulk correction from marking four hundred cases unread overnight.": "The changes that make a case of this type unread again for the people who have already seen it. Leave it empty for the default: the status moved, a document arrived, somebody wrote. A change that is not named here is a technical touch and lights up nothing, which is what keeps a bulk correction from marking four hundred cases unread overnight.",
