        "Old type, kept for this field": "Old type, kept for this field",
        "Old type. Use {type} instead.": "Old type. Use {type} instead.",
        "Old type. Use {type} with format {format} instead.": "Old type. Use {type} with format {format} instead.",
        "One choice per line": "One choice per line",
        "Pattern": "Pattern",
        "Plain text": "Plain text",
        "Reading a built-in copy of the field vocabulary. Update OpenRegister to read the list this instance itself accepts.": "Reading a built-in copy of the field vocabulary. Update OpenRegister to read the list this instance itself accepts.",
        "Reference to another object": "Reference to another object",
        "Repeating": "Repeating",
        "The sentence a handler reads under the field.": "The sentence a handler reads under the field.",
        "This field has the type {type}, which this instance does not offer. dossiq keeps it as it is.": "This field has the type {type}, which this instance does not offer. dossiq keeps it as it is.",
        "Values from a register": "Values from a register",
        "The sentence a handler reads under the field while answering it. One line. This is the field's help: the case form renders it beside the input, not as a heading and not as the field's own documentation. Definition carries the short definition for whoever maintains the case type.": "The sentence a handler reads under the field while answering it. One line. This is the field's help: the case form renders it beside the input, not as a heading and not as the field's own documentation. Definition carries the short definition for whoever maintains the case type.",
        "What kind of answer this field holds. The list is OpenRegister's own property vocabulary, published at /apps/openregister/api/schemas/property-vocabulary and generated from the validator that checks the saved value, so the editor cannot offer a type the engine refuses. The last five values are the ones dossiq used to offer before the vocabulary reached the editor: 'date', 'url' and 'email' are a string with a format, 'enum' is a string with a choice list, and 'json' is an object. They stay accepted so a stored definition keeps working and keeps its value. Nothing rewrites them, the editor offers them only on the definition that already carries one, and each one names its replacement.": "What kind of answer this field holds. The list is OpenRegister's own property vocabulary, published at /apps/openregister/api/schemas/property-vocabulary and generated from the validator that checks the saved value, so the editor cannot offer a type the engine refuses. The last five values are the ones dossiq used to offer before the vocabulary reached the editor: 'date', 'url' and 'email' are a string with a format, 'enum' is a string with a choice list, and 'json' is an object. They stay accepted so a stored definition keeps working and keeps its value. Nothing rewrites them, the editor offers them only on the definition that already carries one, and each one names its replacement.",
        "Which kind of text this is, for a string field. OpenRegister publishes the list: date, date-time, email, url, markdown, html, bsn and 27 more. Leave it empty for plain text. Adding a format to a field that already holds answers is breaking, so OpenRegister rechecks every stored value against it.": "Which kind of text this is, for a string field. OpenRegister publishes the list: date, date-time, email, url, markdown, html, bsn and 27 more. Leave it empty for plain text. Adding a format to a field that already holds answers is breaking, so OpenRegister rechecks every stored value against it.",
        "A regular expression the answer must match. OpenRegister enforces it. dossiq declares it and validates nothing itself.": "A regular expression the answer must match. OpenRegister enforces it. dossiq declares it and validates nothing itself.",
        "The lowest number this field accepts. Only meaningful on a number or integer field.": "The lowest number this field accepts. Only meaningful on a number or integer field.",
        "The highest number this field accepts. Only meaningful on a number or integer field.": "The highest number this field accepts. Only meaningful on a number or integer field.",
        "List entry": "List entry",
        "What one entry of a list looks like, as {\"type\": \"string\"}. Only used when the type is array. The vocabulary's 'items' key takes a shape rather than a type name, so storing the name alone would forward something malformed.": "What one entry of a list looks like, as {\"type\": \"string\"}. Only used when the type is array. The vocabulary's 'items' key takes a shape rather than a type name, so storing the name alone would forward something malformed.",
        "The schema a reference points at, by slug. This is how a field holds another case or a catalogued object instead of text.": "The schema a reference points at, by slug. This is how a field holds another case or a catalogued object instead of text.",
        "A JSON expression that derives this answer from other fields, evaluated by OpenRegister. A Twig expression is not accepted: the JSON form is diffable and an auditor can read it a year later, which is the decision this field carries.": "A JSON expression that derives this answer from other fields, evaluated by OpenRegister. A Twig expression is not accepted: the JSON form is diffable and an auditor can read it a year later, which is the decision this field carries.",
        "The register this field's values come from, such as bag. integriq resolves it. dossiq stores the answer and ships no resolver. The case form does not read it yet: OpenRegister owns the key x-openregister-property-source and has not published it, and a form may only forward a key the vocabulary holds.": "The register this field's values come from, such as bag. integriq resolves it. dossiq stores the answer and ships no resolver. The case form does not read it yet: OpenRegister owns the key x-openregister-property-source and has not published it, and a form may only forward a key the vocabulary holds.",
        "The answers this field accepts, one per entry. OpenRegister's `enum` constraint applies to every type, so a choice list is not a type of its own: a text field, a number field or a date field can each limit its answers to a list. Leave it empty and the field takes any answer its type allows. A field whose stored type is the old 'enum' keeps its values here.": "The answers this field accepts, one per entry. OpenRegister's `enum` constraint applies to every type, so a choice list is not a type of its own: a text field, a number field or a date field can each limit its answers to a list. Leave it empty and the field takes any answer its type allows. A field whose stored type is the old 'enum' keeps its values here.",
