        "This case can still be recovered, so it is not destroyed yet.": "This case can still be recovered, so it is not destroyed yet.",
        "Destroying role": "Destroying role",
        "The group whose members may destroy a deleted case of this type. Destroying is a second act after deleting, and it cannot be undone, so the right is named per case type: a melding and a bezwaar do not need the same seniority behind it. A case type that names no group refuses every destruction except an administrator's, which is the same answer OpenRegister's own destroy right gives.": "The group whose members may destroy a deleted case of this type. Destroying is a second act after deleting, and it cannot be undone, so the right is named per case type: a melding and a bezwaar do not need the same seniority behind it. A case type that names no group refuses every destruction except an administrator's, which is the same answer OpenRegister's own destroy right gives.",
        "Recovery window in days": "Recovery window in days",
        "How many days a deleted case of this type can still be recovered. OpenRegister keeps the recycle state and the window, and dossiq refuses a destruction while this many days have not passed. Leave it empty to use the window the instance already applies.": "How many days a deleted case of this type can still be recovered. OpenRegister keeps the recycle state and the window, and dossiq refuses a destruction while this many days have not passed. Leave it empty to use the window the instance already applies.",
        "Lawful purpose retention in months": "Lawful purpose retention in months",
        "How many months the personal data in a case of this type still has a lawful purpose after the case closes (AVG art. 5.1e). This is not the Archiefwet period: that one comes from the selectielijst through the result type, and the two are kept apart on purpose.": "How many months the personal data in a case of this type still has a lawful purpose after the case closes (AVG art. 5.1e). This is not the Archiefwet period: that one comes from the selectielijst through the result type, and the two are kept apart on purpose.",
        "Lawful purpose ends": "Lawful purpose ends",
        "The day the personal data in this case stops having a lawful purpose (AVG art. 5.1e). Counted from the case's end date and the case type's own retention, never from the archive action date. The two clocks disagree on purpose, and a case that carries one date answers whichever question it was built for and gets the other one wrong.": "The day the personal data in this case stops having a lawful purpose (AVG art. 5.1e). Counted from the case's end date and the case type's own retention, never from the archive action date. The two clocks disagree on purpose, and a case that carries one date answers whichever question it was built for and gets the other one wrong.",
