        "What your team gave itself. The applicant was not told this.": "What your team gave itself. The applicant was not told this.",
        "A fixed closing date for this case type, instead of a lead time. A subsidy round closes on a date, not so many days after each application. Fill this in and every case of this type ends on this day, whenever it came in. A date that has already passed still creates the case, with a term that reads expired.": "A fixed closing date for this case type, instead of a lead time. A subsidy round closes on a date, not so many days after each application. Fill this in and every case of this type ends on this day, whenever it came in. A date that has already passed still creates the case, with a term that reads expired.",
        "Chain term in days": "Chain term in days",
        "Fixed closing date": "Fixed closing date",
        "How many working days before the planned end you want to be warned. This warning is its own, so passing it says nothing about the statutory term.": "How many working days before the planned end you want to be warned. This warning is its own, so passing it says nothing about the statutory term.",
        "How many working days before the statutory term ends you want to be warned. Leave it empty and the escalation ladder decides.": "How many working days before the statutory term ends you want to be warned. Leave it empty and the escalation ladder decides.",
        "How many working days this phase gets, counted on the calendar your organisation administers. An ontvankelijkheidstoets can have its own two weeks inside an eight week term. The clock starts when a case enters this phase and stops when it leaves. A phase that runs over shows as overdue on the case while the case term still reads on time, and it never moves the case term.": "How many working days this phase gets, counted on the calendar your organisation administers. An ontvankelijkheidstoets can have its own two weeks inside an eight week term. The clock starts when a case enters this phase and stops when it leaves. A phase that runs over shows as overdue on the case while the case term still reads on time, and it never moves the case term.",
        "Internal target in days": "Internal target in days",
        "Kind of clock": "Kind of clock",
        "Maximum suspension in days": "Maximum suspension in days",
        "One term for the whole chain of phases, in working days, split over the phases by the share each declares. A phase that overruns shrinks the phases after it. The chain end never moves, so a chain whose phases have eaten it reports zero days left rather than a later date.": "One term for the whole chain of phases, in working days, split over the phases by the share each declares. A phase that overruns shrinks the phases after it. The chain end never moves, so a chain whose phases have eaten it reports zero days left rather than a later date.",
