        "Share of the chain term, in percent": "Share of the chain term, in percent",
        "The day work on this case is planned to start. A case carrying one shows it in the working list, so a handler can see what is coming as well as what is due.": "The day work on this case is planned to start. A case carrying one shows it in the working list, so a handler can see what is coming as well as what is due.",
        "The longest suspension this case type allows, in days. Awb 4:5 bounds the pause as well as the extension, so a suspension asked for beyond this is refused and the refusal names the maximum. Leave it empty and a suspension is bounded only by suspensionAllowed.": "The longest suspension this case type allows, in days. Awb 4:5 bounds the pause as well as the extension, so a suspension asked for beyond this is refused and the refusal names the maximum. Leave it empty and a suspension is bounded only by suspensionAllowed.",
        "The missing items named in a request to the applicant, or the ones that came back with the aanvulling. Asking and suspending the term are one act under Awb 4:5, so one record carries what was asked, when it was asked, and the suspension it caused.": "The missing items named in a request to the applicant, or the ones that came back with the aanvulling. Asking and suspending the term are one act under Awb 4:5, so one record carries what was asked, when it was asked, and the suspension it caused.",
        "The phase this clock belongs to. Filled in on a phase term and empty on the other three kinds.": "The phase this clock belongs to. Filled in on a phase term and empty on the other three kinds.",
        "The working days a teamleider steers on, clocked apart from the statutory term. It never appears on a citizen surface and is never quoted in a message to an applicant.": "The working days a teamleider steers on, clocked apart from the statutory term. It never appears on a citizen surface and is never quoted in a message to an applicant.",
        "The working days your team gives itself to finish a case of this type. This is the service norm, not the law. It runs beside the statutory term and is warned on separately, so a case can be late against the plan and on time against the Awb.": "The working days your team gives itself to finish a case of this type. This is the service norm, not the law. It runs beside the statutory term and is warned on separately, so a case can be late against the plan and on time against the Awb.",
        "This phase's share of the chain term, as a percentage. Use it when the case type declares one term for the whole chain and you want it split over the phases. The shares of the phases after an overrunning one are recomputed, and the chain end stays where it was.": "This phase's share of the chain term, as a percentage. Use it when the case type declares one term for the whole chain and you want it split over the phases. The shares of the phases after an overrunning one are recomputed, and the chain end stays where it was.",
