        "Reversed by": "Reversed by",
        "Content template": "Content template",
        "Reusable step": "Reusable step",
        "Shipped origin": "Shipped origin",
        "Starter set adoption": "Starter set adoption",
        "When the object was written.": "When the object was written.",
        "Seeded at": "Seeded at",
        "The name of the adopted set.": "The name of the adopted set.",
        "The name of the shipped set, for example vth or gemeentelijke-rollen.": "The name of the shipped set, for example vth or gemeentelijke-rollen.",
        "Set": "Set",
        "The version of the set this object was seeded from.": "The version of the set this object was seeded from.",
        "The version that was adopted.": "The version that was adopted.",
        "Set version": "Set version",
        "The named set this role type was shipped in, for example gemeentelijke-rollen. Empty means the role was authored here.": "The named set this role type was shipped in, for example gemeentelijke-rollen. Empty means the role was authored here.",
        "The case template this case was started from, so a change to the template can be traced to the cases that predate it.": "The case template this case was started from, so a change to the template can be traced to the cases that predate it.",
        "Started from template": "Started from template",
